          questions: READER_QUESTION_BANK.slice(0, MAX_QUESTIONS),
        },
      }),
      notice:
        "General questions — connect a model in Settings for ones about this passage.",
    };
  }
  if (element.type !== "SentenceLab" && element.type !== "ReaderQuestions")
