  const stream = createToolStream(seed, max);
  const brief = [
    context.goal && `The piece's goal: ${context.goal.slice(0, 400)}`,
    context.audience && `Its reader: ${context.audience.slice(0, 400)}`,
  ]
    .filter(Boolean)
    .join("\n");
