let unlocked = false;
export function unlockSpeechPlayback(): void {
  if (unlocked || typeof window === "undefined") return;
  audio = audio ?? new Audio();
  audio.muted = true;
  audio.src = SILENCE;
  const started = audio.play();
  if (started && typeof started.then === "function") {
    void started
      .then(() => {
        unlocked = true;
      })
