import { addProviderMarkup } from "@notorganic/core";
import { GatewayError } from "./errors";
import { PortkeyProxy } from "./proxy";
import type { RealtimeUpgradeContext } from "./realtime";
import type { GatewayConfig, VerifiedPrincipal } from "./types";

const CLOSE = JSON.stringify({ type: "session.close" });
const invalid = () =>
  new GatewayError(
    400,
    "invalid_request_error",
    "Unsupported GPT-Live event or configuration.",
    "invalid_live_event",
  );

/** Restricts the Live protocol, not the legacy Realtime protocol. No paid delegation. */
export class LiveSessionPolicy {
  readonly closeMessage = CLOSE;
  private startSent = false;
  private ready = false;
  private closing = false;
  private startedAt = 0;
  private audioBytes = 0;
  finalSeconds?: number;

  constructor(
    readonly maxDurationMs: number,
    private readonly now = Date.now,
  ) {}

  get dispatched(): boolean {
    return this.startSent;
  }

  clientMessage(message: string): string {
    if (Buffer.byteLength(message) > 131_072 || this.closing) throw invalid();
    let event: Record<string, unknown>;
    try {
      event = JSON.parse(message);
    } catch {
      throw invalid();
    }
    if (!event || typeof event !== "object" || Array.isArray(event))
      throw invalid();
    const eventId =
      typeof event.event_id === "string" && event.event_id.length <= 128
        ? event.event_id
        : undefined;
    if (event.type === "session.close") {
      this.closing = true;
      return CLOSE;
    }
    if (event.type === "session.start") {
      if (this.startSent) throw invalid();
      const session = event.session as Record<string, unknown> | undefined;
      if (
        !session ||
        typeof session !== "object" ||
        Array.isArray(session) ||
        Object.keys(session).some((key) => key !== "instructions") ||
        typeof session.instructions !== "string" ||
        session.instructions.length > 16_000
      )
        throw invalid();
      this.startSent = true;
      return JSON.stringify({
        type: "session.start",
        event_id: eventId,
        session: {
          model: "gpt-live-1",
          instructions: session.instructions,
          store: false,
          audio: {
            format: { type: "audio/pcm", rate: 24000 },
            output: { voice: "marin" },
          },
          delegation: { type: "client" },
        },
      });
    }
    if (!this.ready) throw invalid();
    if (event.type === "session.input_audio.append") {
      if (
        typeof event.audio !== "string" ||
        !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(
          event.audio,
        )
      )
        throw invalid();
      const bytes = Buffer.from(event.audio, "base64").byteLength;
      // PCM16/24 kHz, at most one second per chunk and one second of lead.
      if (
        !bytes ||
        bytes % 2 ||
        bytes > 48_000 ||
        this.audioBytes + bytes >
          (Math.max(0, this.now() - this.startedAt) / 1000 + 1) * 48_000
      )
        throw invalid();
      this.audioBytes += bytes;
      return JSON.stringify({ type: event.type, audio: event.audio });
    }
    if (
      event.type === "session.input_audio.mute" ||
      event.type === "session.input_audio.unmute"
    ) {
      return JSON.stringify({ type: event.type, event_id: eventId });
    }
    if (
      [
        "session.instructions.append",
        "session.thinking.append",
        "session.commentary.append",
      ].includes(String(event.type))
    ) {
      if (
        typeof event.content !== "string" ||
        !event.content.length ||
        event.content.length > 500 ||
        event.delegation_id !== null
      )
        throw invalid();
      return JSON.stringify({
        type: event.type,
        event_id: eventId,
        content: event.content,
        delegation_id: null,
      });
    }
    // No response.create, arbitrary tools, model/voice changes, storage, or usage injection.
    throw invalid();
  }

  serverMessage(message: string): boolean {
    let event: { type?: string; usage?: { seconds?: unknown } };
    try {
      event = JSON.parse(message);
    } catch {
