  protectedRoute(
    app,
    tokens,
    "get",
    "/v1/realtime",
    "realtime:connect",
    async (c) => {
      const principal = c.get("principal");
      if (
        !(await config.store.hasRealtimeConsent({
          accountId: principal.accountId,
        }))
      ) {
        throw new GatewayError(
          403,
          "permission_error",
          "Realtime requires explicit content-logging consent.",
          "realtime_consent_required",
        );
      }
      if (!dependencies.realtime) {
        throw new GatewayError(
          426,
          "invalid_request_error",
          "This deployment does not provide a WebSocket upgrade adapter.",
          "upgrade_required",
        );
      }
      const reservation = await proxy.reserveRealtime(c.req.raw, principal);
      return dependencies.realtime.upgrade(c.req.raw, {
        principal,
        upstreamUrl: `${(
          config.portkeyBaseUrl ?? "https://api.portkey.ai/v1"
        ).replace(/^http/, "ws")}/realtime`,
        upstreamHeaders: await proxy.portkeyHeaders(
          principal,
          reservation.requestId,
          true,
          "realtime",
        ),
        onAccepted: async () =>
          await proxy.acceptRealtime(reservation.requestId),
        onClosed: async (accepted) =>
          await proxy.closeRealtime(reservation, accepted),
      });
    },
  );

  protectedRoute(
    app,
    tokens,
    "get",
    "/v1/live/sessions",
    "realtime:connect",
    async (c) => {
      if (!dependencies.realtime) {
        throw new GatewayError(
          426,
          "invalid_request_error",
          "A WebSocket upgrade adapter is required.",
          "upgrade_required",
        );
      }
      if (c.req.header("upgrade")?.toLowerCase() !== "websocket") {
        throw new GatewayError(
          426,
          "invalid_request_error",
          "Connect to Live using a WebSocket.",
          "upgrade_required",
        );
      }
      const context = await liveContext(config, c.req.raw, c.get("principal"));
      try {
        return await dependencies.realtime.upgrade(c.req.raw, context);
      } catch (error) {
        await context.onClosed(false);
        throw error;
      }
    },
  );

  return app;
}

