{"chunk_id":"359f96","wall_time_seconds":0.000017956,"exit_code":0,"original_token_count":2051,"output":"import { addProviderMarkup } from "@notorganic/core";
import { GatewayError } from "./errors";
import { PortkeyProxy } from "./proxy";
import type { RealtimeUpgradeContext } from "./realtime";
import type { GatewayConfig, VerifiedPrincipal } from "./types";

const CLOSE = JSON.stringify({ type: "session.close" });
const invalid = () =>
  new GatewayError(
    400,
    "invalid_request_error",
    "Unsupported GPT-Live event or configuration.",
    "invalid_live_event",
  );

/** Restricts the Live protocol, not the legacy Realtime protocol. No paid delegation. */
export class LiveSessionPolicy {
  readonly closeMessage = CLOSE;
  private startSent = false;
  private ready = false;
  private closing = false;
  private startedAt = 0;
  private audioBytes = 0;
  finalSeconds?: number;

  constructor(
    readonly maxDurationMs: number,
    private readonly now = Date.now,
  ) {}

  get dispatched(): boolean {
    return this.startSent;
  }

  clientMessage(message: string): string {
    if (Buffer.byteLength(message) > 131_072 || this.closing) throw invalid();
    let event: Record<string, unknown>;
    try {
      event = JSON.parse(message);
    } catch {
      throw invalid();
    }
    if (!event || typeof event !== "object" || Array.isArray(event))
      throw invalid();
    const eventId =
      typeof event.event_id === "string" && event.event_id.length <= 128
        ? event.event_id
        : undefined;
    if (event.type === "session.close") {
      this.closing = true;
      return CLOSE;
    }
    if (event.type === "session.start") {
      if (this.startSent) throw invalid();
      const session = event.session as Record<string, unknown> | undefined;
      if (
        !session ||
        typeof session !== "object" ||
        Array.isArray(session) ||
        Object.keys(session).some((key) => key !== "instructions") ||
        typeof session.instructions !== "string" ||
        session.instructions.length > 16_000
      )
        throw invalid();
      this.startSent = true;
      return JSON.stringify({
        type: "session.start",
        event_id: eventId,
        session: {
          model: "gpt-live-1",
          instructions: session.instructions,
          store: false,
          audio: {
            format: { type: "audio/pcm", rate: 24000 },
            output: { voice: "marin" },
          },
          delegation: { type: "client" },
        },
      });
    }
    if (!this.ready) throw invalid();
    if (event.type === "session.input_audio.append") {
      if (
        typeof event.audio !== "string" ||
        !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(
          event.audio,
        )
      )
        throw invalid();
      const bytes = Buffer.from(event.audio, "base64").byteLength;
      // PCM16/24 kHz, at most one second per chunk and one second of lead.
      if (
        !bytes ||
        bytes % 2 ||
        bytes > 48_000 ||
        this.audioBytes + bytes >
          (Math.max(0, this.now() - this.startedAt) / 1000 + 1) * 48_000
      )
        throw invalid();
      this.audioBytes += bytes;
      return JSON.stringify({ type: event.type, audio: event.audio });
    }
    if (
      event.type === "session.input_audio.mute" ||
      event.type === "session.input_audio.unmute"
    ) {
      return JSON.stringify({ type: event.type, event_id: eventId });
    }
    if (
      [
        "session.instructions.append",
        "session.thinking.append",
        "session.commentary.append",
      ].includes(String(event.type))
    ) {
      if (
        typeof event.content !== "string" ||
        !event.content.length ||
        event.content.length > 500 ||
        event.delegation_id !== null
      )
        throw invalid();
      return JSON.stringify({
        type: event.type,
        event_id: eventId,
        content: event.content,
        delegation_id: null,
      });
    }
    // No response.create, arbitrary tools, model/voice changes, storage, or usage injection.
    throw invalid();
  }

  serverMessage(message: string): boolean {
    let event: { type?: string; usage?: { seconds?: unknown } };
    try {
      event = JSON.parse(message);
    } catch {
      return false;
    }
    if (!event || typeof event !== "object") return false;
    if (event.type === "session.started" && !this.ready) {
      this.ready = true;
      this.startedAt = this.now();
    }
    if (event.type !== "session.closed") return false;
    this.closing = true;
    const seconds = event.usage?.seconds;
    if (typeof seconds === "number" && Number.isFinite(seconds) && seconds >= 0)
      this.finalSeconds = seconds;
    return true;
  }
}

export async function liveContext(
  config: GatewayConfig,
  request: Request,
  principal: VerifiedPrincipal,
): Promise<RealtimeUpgradeContext> {
  const live = config.live;
  const upstreamPerMinute = live?.upstreamMicrousdPerMinute ??
    (live?.upstreamMicrousdPerSecond === undefined ? 0 : live.upstreamMicrousdPerSecond * 60);
  if (
    !live?.apiKey ||
    !Number.isSafeInteger(upstreamPerMinute) ||
    upstreamPerMinute <= 0
  ) {
    throw new GatewayError(
      503,
      "api_error",
      "GPT-Live is not configured.",
      "live_unavailable",
    );
  }
  if (new URL(request.url).search)
    throw new GatewayError(
      400,
      "invalid_request_error",
      "Live does not accept query parameters.",
      "invalid_live_query",
    );
  if (config.enabledAliases && !config.enabledAliases.includes("realtime")) {
    throw new GatewayError(
      403,
      "permission_error",
      "Realtime is disabled.",
      "model_not_enabled",
    );
  }
  if (
    !(await config.store.hasRealtimeConsent({ accountId: principal.accountId }))
  ) {
    throw new GatewayError(
      403,
      "permission_error",
      "Live requires explicit content-logging consent.",
      "realtime_consent_required",
    );
  }
  // Keep the published minute rate exact; never round it to an integer second rate.
  const ratePerMinute = addProviderMarkup(upstreamPerMinute);
  const chargeForSeconds = (seconds: number) => Math.ceil(seconds * ratePerMinute / 60);
  const budget = Number(request.headers.get("x-notorganic-max-cost-microusd"));
  // Reserve 15 seconds for graceful close plus one second of rounding headroom.
  if (!Number.isSafeInteger(budget) || budget < chargeForSeconds(31)) {
    throw new GatewayError(
      400,
      "invalid_request_error",
      "Live budget must cover at least 31 seconds at the configured rate.",
      "live_budget_too_small",
    );
  }
  const proxy = new PortkeyProxy(config);
  const reservation = await proxy.reserveRealtime(request, principal, "live");
  const policy = new LiveSessionPolicy(
    Math.min(25 * 60, Math.floor(budget * 60 / ratePerMinute) - 16) * 1000,
    config.now,
  );
  let finalized = false;
  return {
    principal,
    sessionPolicy: policy,
    upstreamUrl: "wss://api.openai.com/v1/live/sessions",
    upstreamHeaders: new Headers({ Authorization: `Bearer ${live.apiKey}` }),
    onAccepted: () => proxy.acceptRealtime(reservation.requestId),
    onClosed: async () => {
      if (finalized) return;
      finalized = true;
      if (!policy.dispatched) {
        await config.store.release({
          requestId: reservation.requestId,
          reason: "live_not_started",
        });
      } else if (policy.finalSeconds === undefined) {
        await config.store.reconcile({
          requestId: reservation.requestId,
          conservativeCostMicrousd: budget,
          reason: "live_final_usage_unconfirmed",
        });
      } else {
        // This route uses WebSockets. The documented 15-second initialization
        // charge belongs to WebRTC POST creation, not a WebSocket billing floor.
        const charge = chargeForSeconds(policy.finalSeconds);
        await config.store.settle({
          requestId: reservation.requestId,
          actualCostMicrousd: Math.min(charge, budget),
          providerAbsorbedMicrousd: Math.max(0, charge - budget),
          usage: {
            live_seconds: policy.finalSeconds,
            live_billable_seconds: policy.finalSeconds,
          },
        });
      }
    },
  };
