import type { Editor } from "@tiptap/core";
import type { LiveAction } from "./live-voice-contract";

let current: Editor | null = null;
let generation = 0;
export function registerVoiceEditor(editor: Editor): () => void {
  current = editor; generation++;
  return () => { if (current === editor) { current = null; generation++; } };
}
export function invalidateVoiceWorkspace() { generation++; }
export function voiceWorkspace() {
  const editor = current;
  if (!editor || editor.isDestroyed) return null;
  const { from, to } = editor.state.selection;
  return { text: editor.getText().slice(0, 20_000), selection: editor.state.doc.textBetween(from, to, "\n").slice(0, 8000), revision: `${generation}:${editor.getHTML()}` };
}

/** Text-node positions preserve formatting outside the requested passage. Ambiguous matches never edit. */
export function voiceMatches(editor: Editor, text: string) {
  const matches: Array<{ from: number; to: number }> = [];
  if (!text.trim()) return matches;
  editor.state.doc.descendants((node, pos) => {
    if (!node.isTextblock) return true;
    const plain = node.textBetween(0, node.content.size, "", "\uFFFC");
    let offset = plain.indexOf(text);
    while (offset !== -1) {
      matches.push({ from: pos + 1 + offset, to: pos + 1 + offset + text.length });
      offset = plain.indexOf(text, offset + Math.max(1, text.length));
    }
    return false;
  });
  return matches;
}
export function findVoicePassage(text: string): string {
  if (!current) throw new Error("Open a manuscript first.");
  const matches = voiceMatches(current, text);
  if (!matches.length) return "That phrase was not found in the manuscript.";
  current.chain().setTextSelection(matches[0]).scrollIntoView().run();
  return `Selected the ${matches.length > 1 ? "first of " + matches.length + " matches" : "matching passage"}.`;
}
export function applyVoiceEdit(action: LiveAction, revision: string): string {
  const editor = current;
  if (!editor || editor.isDestroyed || !editor.isEditable) throw new Error("This manuscript is not editable.");
  if (voiceWorkspace()?.revision !== revision) throw new Error("The draft changed. Ask for a fresh edit before applying it.");
  const paragraphs = action.text.split(/\n\s*\n/).map(text => ({ type: "paragraph", content: text ? [{ type: "text", text }] : [] }));
  if (action.kind === "append") {
    if (!action.text.trim()) throw new Error("There is no text to add.");
    if (!editor.chain().insertContentAt(editor.state.doc.content.size, paragraphs).run()) throw new Error("The text could not be added.");
  } else if (action.kind === "replace") {
    const matches = voiceMatches(editor, action.original);
    if (matches.length !== 1) throw new Error("The passage is missing or appears more than once. Select a unique passage and try again.");
    const content = action.text ? (action.text.includes("\n") ? paragraphs : [{ type: "text", text: action.text }]) : [];
    if (!editor.chain().insertContentAt(matches[0], content).run()) throw new Error("The edit could not be applied.");
  } else throw new Error("This is not a draft edit.");
  return "Applied to the manuscript. You can undo it in the editor.";
}

export const LIVE_OPEN_EVENT = "twyne:live-voice-open";
export function openLiveVoice(author?: string, passage?: string) {
  window.dispatchEvent(new CustomEvent(LIVE_OPEN_EVENT, { detail: { author, passage } }));
}

const WORKLET = `class TwynePcm extends AudioWorkletProcessor {
 constructor(){super();this.samples=new Int16Array(2400);this.index=0;}
 process(inputs){const channel=inputs[0]?.[0];if(!channel)return true;
 for(const value of channel){const s=Math.max(-1,Math.min(1,value));this.samples[this.index++]=s<0?s*32768:s*32767;
 if(this.index===2400){this.port.postMessage(this.samples.buffer,[this.samples.buffer]);this.samples=new Int16Array(2400);this.index=0;}}return true;}
} registerProcessor('twyne-pcm',TwynePcm);`;

/** A single audio clock for microphone capture and speech, with echo cancellation. */
export async function liveVoiceAudio(onChunk: (audio: string, level: number) => void) {
  if (!navigator.mediaDevices?.getUserMedia) throw new Error("Live voice needs microphone access over HTTPS.");
  const context = new AudioContext({ sampleRate: 24_000 });
  // Resume in the initiating gesture, before the microphone permission prompt.
  const resumed = context.resume();
  let stream: MediaStream | null = null;
  let source: MediaStreamAudioSourceNode | null = null;
  let node: AudioWorkletNode | null = null;
  let silent: GainNode | null = null;
  let nextTime = 0;
  let stopped = false;
  const playing = new Set<AudioBufferSourceNode>();
  const stop = () => {
    if (stopped) return;
    stopped = true;
    stream?.getTracks().forEach(track => track.stop());
    if (node) node.port.onmessage = null;
    node?.disconnect(); source?.disconnect(); silent?.disconnect();
    playing.forEach(audio => { try { audio.stop(); } catch { /* ended */ } });
    playing.clear(); void context.close();
  };
  try {
    stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } });
    await resumed;
    if (context.sampleRate !== 24_000 || !context.audioWorklet) throw new Error("This browser cannot capture Live audio at 24 kHz.");
    const url = URL.createObjectURL(new Blob([WORKLET], { type: "application/javascript" }));
    try { await context.audioWorklet.addModule(url); } finally { URL.revokeObjectURL(url); }
    source = context.createMediaStreamSource(stream);
    node = new AudioWorkletNode(context, "twyne-pcm");
    silent = context.createGain(); silent.gain.value = 0;
    node.port.onmessage = ({ data }: MessageEvent<ArrayBuffer>) => {
      if (stopped) return;
      const bytes = new Uint8Array(data);
      const pcm = new Int16Array(data);
      let sum = 0;
      for (const sample of pcm) sum += (sample / 32768) ** 2;
      onChunk(btoa(String.fromCharCode(...bytes)), Math.min(1, Math.sqrt(sum / pcm.length) * 5));
    };
    source.connect(node); node.connect(silent); silent.connect(context.destination);
    return {
      stop,
      mute(value: boolean) { stream?.getAudioTracks().forEach(track => { track.enabled = !value; }); },
      play(base64: string, onEnd: () => void) {
        if (stopped) return;
        if (context.state !== "running") throw new Error("Audio playback is paused by your browser. End the session and start again.");
        const bytes = Uint8Array.from(atob(base64), c => c.charCodeAt(0));
        if (!bytes.length || bytes.length % 2) throw new Error("Invalid Live audio.");
        const pcm = new DataView(bytes.buffer);
        const buffer = context.createBuffer(1, bytes.length / 2, 24_000);
        const samples = buffer.getChannelData(0);
        for (let i = 0; i < samples.length; i++) samples[i] = pcm.getInt16(i * 2, true) / 32768;
        if (nextTime - context.currentTime > 5) throw new Error("Speech playback fell behind. Reconnect to continue.");
        const audio = context.createBufferSource(); audio.buffer = buffer; audio.connect(context.destination);
        playing.add(audio);
        audio.onended = () => { audio.disconnect(); playing.delete(audio); if (!playing.size) onEnd(); };
        const start = Math.max(context.currentTime, nextTime);
        nextTime = start + buffer.duration; audio.start(start);
      },
    };
  } catch (error) { stop(); throw error; }
}

