      title?: string;
      author?: string;
      publisher?: string;
      date?: string;
      markdown?: string;
      text?: string;
      embeddable?: boolean;
    };
    return {
      title: data.title ?? url,
      author: data.author,
      publisher: data.publisher,
      date: data.date,
      markdown: data.markdown ?? data.text ?? "",
      embeddable: data.embeddable ?? false,
    };
  } catch {
    return null;
  }
