      });
    }

    if (identity && researchApiKey()) {
      const r = await providerSearch(args.query, args.context ?? "");
      if (r.length > 0) return { results: r, provider: "tinyfish" };
    }
    return {
      results: localSearch(args.query, args.context ?? ""),
      provider: "local",
    };
  },
