import { describe, expect, test } from "bun:test";
import { LiveSessionPolicy } from "./live";

const start = JSON.stringify({
  type: "session.start",
  session: { instructions: "Ask the authored survey question." },
});

describe("GPT-Live protocol policy", () => {
  test("pins provider configuration and rejects arbitrary paid delegation", () => {
    const policy = new LiveSessionPolicy(30_000);
    const event = JSON.parse(policy.clientMessage(start));
    expect(event.session.model).toBe("gpt-live-1");
    expect(event.session.delegation).toEqual({ type: "client" });
    expect(event.session.store).toBe(false);
    expect(event.session.audio.format).toEqual({
      type: "audio/pcm",
      rate: 24000,
    });
    expect(() => policy.clientMessage(start)).toThrow();
    for (const session of [
      { model: "another", instructions: "a" },
      { instructions: "a", delegation: { type: "responses" } },
      { instructions: "a", store: true },
    ]) {
      expect(() =>
        new LiveSessionPolicy(30_000).clientMessage(
          JSON.stringify({ type: "session.start", session }),
        ),
      ).toThrow();
    }
  });

  test("requires readiness and paces complete PCM samples", () => {
    let now = 0;
    const policy = new LiveSessionPolicy(30_000, () => now);
    const audio = JSON.stringify({
      type: "session.input_audio.append",
      audio: Buffer.alloc(48_000).toString("base64"),
    });
    policy.clientMessage(start);
    expect(() => policy.clientMessage(audio)).toThrow();
    policy.serverMessage('{"type":"session.started"}');
    expect(() => policy.clientMessage(audio)).not.toThrow();
    expect(() => policy.clientMessage(audio)).toThrow();
    now = 1000;
    expect(() => policy.clientMessage(audio)).not.toThrow();
    for (const value of ["?", "YQ==", "", "a".repeat(150_000)]) {
      expect(() =>
        policy.clientMessage(
          JSON.stringify({ type: "session.input_audio.append", audio: value }),
        ),
      ).toThrow();
    }
  });

  test("only trusted terminal snapshots supply final usage", () => {
    const policy = new LiveSessionPolicy(30_000);
    policy.clientMessage(start);
    policy.serverMessage('{"type":"session.started"}');
    expect(() =>
      policy.clientMessage('{"type":"session.closed","usage":{"seconds":0}}'),
    ).toThrow();
    expect(() => policy.clientMessage('{"type":"response.create"}')).toThrow();
    policy.serverMessage(
      '{"type":"session.usage.updated","usage":{"seconds":10}}',
    );
    policy.serverMessage(
      '{"type":"session.usage.updated","usage":{"seconds":20}}',
    );
    expect(policy.finalSeconds).toBeUndefined();
    expect(
      policy.serverMessage(
        '{"type":"session.closed","usage":{"seconds":21.5}}',
      ),
    ).toBe(true);
    expect(policy.finalSeconds).toBe(21.5);
    expect(() => policy.clientMessage(start)).toThrow();
  });

  test("invalid final usage remains unknown", () => {
    for (const seconds of [-1, "0", null, undefined]) {
      const policy = new LiveSessionPolicy(30_000);
      expect(
        policy.serverMessage(
          JSON.stringify({ type: "session.closed", usage: { seconds } }),
        ),
      ).toBe(true);
      expect(policy.finalSeconds).toBeUndefined();
    }
  });

  test("context updates are bounded and stripped to supported fields", () => {
    const policy = new LiveSessionPolicy(30_000);
    policy.clientMessage(start);
    policy.serverMessage('{"type":"session.started"}');
    expect(
      JSON.parse(
        policy.clientMessage(
          JSON.stringify({
            type: "session.thinking.append",
            delegation_id: null,
            content: "The user selected annual billing.",
            secret: "discard",
          }),
        ),
      ),
    ).not.toHaveProperty("secret");
    expect(() =>
      policy.clientMessage(
        JSON.stringify({
          type: "session.thinking.append",
          delegation_id: "invented",
          content: "x",
        }),
      ),
    ).toThrow();
  });
});

