    throw new Error("IDEMPOTENCY_CONFLICT");
  }
  // A terminal attempt that never billed the caller may be retried under
  // the same idempotency key. The old attempt keeps its row (and its
  // released reservation) for audit; we retire its lookup value so the
  // fresh attempt below can claim the key with a new reservation.
  const retryable =
    idempotent.state === "expired" ||
    (idempotent.state === "failed" && (idempotent.billedMicros ?? 0) === 0);
  if (retryable) {
    await ctx.db.patch(idempotent._id, {
      idempotencyLookup: `${idempotencyLookup}\u0000retired:${idempotent.requestId}`,
      updatedAt: now(),
    });
  } else {
    const reservation = await ctx.db.get(idempotent.reservationId);
    if (
      !reservation ||
      reservation.estimatedMicros !== args.estimatedMicros
    ) {
      throw new Error("IDEMPOTENCY_CONFLICT");
    }
    return idempotent;
  }
}
