import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { convexTest } from "convex-test";
import { makeFunctionReference } from "convex/server";
import schema from "../convex/schema";

const modules = {
  "../convex/_generated/server.js": () => import("../convex/_generated/server.js"),
  "../convex/welcomeGrants.ts": () => import("../convex/welcomeGrants"),
  "../convex/inference.ts": () => import("../convex/inference"),
  "../convex/wallet.ts": () => import("../convex/wallet"),
};
const ensureRef = makeFunctionReference<"mutation">("welcomeGrants:ensure");
const beginRef = makeFunctionReference<"mutation">("inference:begin");
const did = "did:plc:welcome";
const secret = "welcome-grant-test-secret";
const args = { serviceSecret: secret, did, product: "keating" };
let previous: string | undefined;
beforeAll(() => { previous = process.env.CONVEX_GATEWAY_SECRET; process.env.CONVEX_GATEWAY_SECRET = secret; });
afterAll(() => { if (previous === undefined) delete process.env.CONVEX_GATEWAY_SECRET; else process.env.CONVEX_GATEWAY_SECRET = previous; });

function harness() { return convexTest(schema, modules); }
const beginArgs = {
  ...args, requestId: "req_welcome", idempotencyKey: "welcome-message", feature: "chat",
  requestHash: "hi", model: "balanced", routeVersion: "active", rateVersion: "current",
  estimatedMicros: 100_000, ttlMs: 60_000,
};

describe("one-time Keating welcome credit", () => {
  test("rejects untrusted caller-selected identities without issuing money", async () => {
    const t = harness();
    await expect(t.mutation(ensureRef, { ...args, serviceSecret: "wrong" })).rejects.toThrow();
    expect(await t.run(ctx => ctx.db.query("grantLots").collect())).toEqual([]);
  });

  test("issues $2.50 once across repeated and concurrent authenticated uses", async () => {
    const t = harness();
    const replies = await Promise.all(Array.from({ length: 8 }, () => t.mutation(ensureRef, args)));
    expect(replies.every(reply => reply.granted && reply.amountMicros === 2_500_000)).toBe(true);
    const lots = await t.run(ctx => ctx.db.query("grantLots").collect());
    expect(lots).toHaveLength(1);
    expect(lots[0]).toMatchObject({ did, program: "keating_welcome", amountMicros: 2_500_000,
      remainingMicros: 2_500_000, productScope: "keating", expiresAt: null,
      idempotencyKey: `keating-welcome:${did}` });
    const entries = await t.run(ctx => ctx.db.query("walletEntries").collect());
    expect(entries).toEqual([]);
  });

  test("never resets spent welcome credit on another sign-in", async () => {
    const t = harness();
    await t.mutation(ensureRef, args);
    await t.run(async ctx => { const lot = (await ctx.db.query("grantLots").unique())!; await ctx.db.patch(lot._id, { remainingMicros: 0 }); });
    expect(await t.mutation(ensureRef, args)).toEqual({ eligible: false, granted: true, amountMicros: 2_500_000, remainingMicros: 0 });
    expect(await t.run(ctx => ctx.db.query("grantLots").collect())).toHaveLength(1);
  });

  test("distinct authenticated DIDs each receive their own single allowance", async () => {
    const t = harness();
    await t.mutation(ensureRef, args);
    await t.mutation(ensureRef, { ...args, did: "did:plc:another" });
    const lots = await t.run(ctx => ctx.db.query("grantLots").collect());
    expect(lots).toHaveLength(2);
    expect(new Set(lots.map(lot => lot.idempotencyKey)).size).toBe(2);
  });

  test("existing authenticated Keating inference receives and reserves welcome funds", async () => {
    const t = harness();
    const request = await t.mutation(beginRef, beginArgs);
    expect(request.state).toBe("reserved");
    const reservation = await t.run(ctx => ctx.db.get(request.reservationId));
    expect(reservation).toMatchObject({ grantMicros: 100_000, cashMicros: 0 });
    expect(await t.mutation(ensureRef, args)).toMatchObject({ granted: true, remainingMicros: 2_400_000 });
  });

  test("other products cannot mint or spend the Keating welcome credit", async () => {
    const t = harness();
    expect(await t.mutation(ensureRef, { ...args, product: "twyne" })).toMatchObject({ eligible: false, granted: false });
    expect(await t.run(ctx => ctx.db.query("grantLots").collect())).toHaveLength(0);
    await t.mutation(ensureRef, args);
    await expect(t.mutation(beginRef, { ...beginArgs, product: "twyne" })).rejects.toThrow();
    expect((await t.mutation(ensureRef, args)).remainingMicros).toBe(2_500_000);
  });

  for (const program of ["keating_pack_10", "stich_credit_25", "twyne_pro"]) {
    test(`historical paid grant excludes a spent or expired account: ${program}`, async () => {
      const t = harness();
      await t.run(ctx => ctx.db.insert("grantLots", {
        did, program, amountMicros: 10_000_000, remainingMicros: 0, productScope: null,
        expiresAt: 1, issuedAt: 0, idempotencyKey: "historical-purchase",
      }));
      expect(await t.mutation(ensureRef, args)).toMatchObject({ eligible: false, granted: false });
      expect(await t.run(ctx => ctx.db.query("grantLots").collect())).toHaveLength(1);
    });
  }

  test("a historical cash deposit excludes the account even after funds were spent", async () => {
    const t = harness();
    await t.run(async ctx => {
      await ctx.db.insert("walletEntries", { did, kind: "deposit", amountMicros: 10_000_000,
        createdAt: 0, idempotencyKey: "paid-cash" });
      // Payment evidence must not fall out of a bounded recent-history window.
      for (let index = 0; index < 260; index++) await ctx.db.insert("walletEntries", {
        did, kind: "inference", amountMicros: -1, createdAt: index + 1, idempotencyKey: `usage:${index}`,
      });
    });
    expect(await t.mutation(ensureRef, args)).toMatchObject({ eligible: false, granted: false });
    expect(await t.run(ctx => ctx.db.query("grantLots").collect())).toEqual([]);
  });

  test("free Interleave allowance is not mistaken for purchased credits", async () => {
    const t = harness();
    await t.run(ctx => ctx.db.insert("grantLots", {
      did, program: "interleave_free", amountMicros: 2_000_000, remainingMicros: 0,
      productScope: "interleave", expiresAt: 1, issuedAt: 0, idempotencyKey: "free-interleave",
    }));
    expect(await t.mutation(ensureRef, args)).toMatchObject({ eligible: true, granted: true, remainingMicros: 2_500_000 });
  });

  for (const state of ["locked", "deleted"] as const) {
    test(`${state} accounts cannot receive a new welcome grant`, async () => {
      const t = harness();
      await t.run(ctx => ctx.db.insert("didAccounts", {
        did, pdsUrl: "https://pds.test", recoveryState: state === "locked" ? "locked" : "active",
        ...(state === "deleted" ? { deletedAt: 1 } : {}), createdAt: 0, updatedAt: 0,
      }));
      expect(await t.mutation(ensureRef, args)).toMatchObject({ granted: false });
    });
  }
});

