  live = await import(`./live-voice?test=${Math.random()}`);
  socket = new Socket(); stops = 0; plays = 0; muted = false;
  capture = { stop: () => { stops++; }, mute: value => { muted = value; }, play: () => { plays++; } };
});
afterEach(() => { live.endLiveVoice(); socket.event({ type: "session.closed", usage: { seconds: 1 } }); });
afterAll(() => {
  for (const name of names) { const descriptor = previous.get(name); if (descriptor) Object.defineProperty(globalThis, name, descriptor); else Reflect.deleteProperty(globalThis, name); }
  release();
});
const credentials = { authorization: "DPoP token", dpop: "proof", idempotencyKey: "once", maxCostMicrousd: 500_000 };
async function connect(action: (ref: unknown, args: unknown) => Promise<unknown> = async () => credentials) {
  await live.startLiveVoice({ action } as unknown as ConvexClient, "Le Lecteur", "This comment", true, {
    audio: async onChunk => { chunks = onChunk; return capture; },
    socket: () => socket as unknown as WebSocket,
  });
  socket.onopen?.(); socket.event({ type: "twyne.live.ready" }); socket.event({ type: "session.started" });
}
test("microphone stays live during output and transcripts grow independently", async () => {
  await connect();
  socket.event({ type: "session.output_audio.delta", delta: "AAA=" });
  chunks("AAA=", .5);
  expect(plays).toBe(1);
  expect(socket.sent.at(-1)?.type).toBe("session.input_audio.append");
  socket.event({ type: "session.input_transcript.delta", delta: "Please ", start_ms: 1, end_ms: 2 });
  socket.event({ type: "session.output_transcript.delta", delta: "I'm listening.", start_ms: 1, end_ms: 3 });
  socket.event({ type: "session.input_transcript.delta", delta: "revise this.", start_ms: 2, end_ms: 4 });
  expect(live.liveVoiceState()).toMatchObject({ userTranscript: "Please revise this.", assistantTranscript: "I'm listening." });
  live.muteLiveVoice(); expect(muted).toBe(true);
  const before = socket.sent.length; chunks("AAA=", .2); expect(socket.sent.length).toBe(before);
  live.endLiveVoice(); expect(stops).toBe(1); expect(live.liveVoiceState().status).toBe("closing");
  expect(socket.sent.at(-1)?.type).toBe("session.close");
  socket.event({ type: "session.closed", usage: { seconds: 10 } });
  expect(live.liveVoiceState()).toMatchObject({ status: "idle", finalized: true });
});
test("cancel during microphone permission stops late capture without purchasing a session", async () => {
  let resolve!: (value: typeof capture) => void;
  let requests = 0;
  const start = live.startLiveVoice({ action: async () => { requests++; return credentials; } } as unknown as ConvexClient, "Le Lecteur", "", true, {
    audio: () => new Promise(done => { resolve = done; }), socket: () => socket as unknown as WebSocket,
  });
  live.endLiveVoice(); resolve(capture); await start;
  expect(stops).toBe(1); expect(requests).toBe(0); expect(live.liveVoiceState().status).toBe("idle");
});
test("repeated delegations run once and results after end cannot act or speak", async () => {
  let calls = 0;
  let resolve!: (result: unknown) => void;
  await connect(async () => { calls++; return calls === 1 ? credentials : new Promise(done => { resolve = done; }); });
  const event = { type: "session.delegation.created", delegation: { id: "task_1", target: "client" } };
  socket.event(event); socket.event(event); expect(calls).toBe(2);
  live.endLiveVoice(); socket.event({ type: "session.closed" });
  resolve({ kind: "answer", text: "A late result", original: "", target: "" });
  await new Promise(done => setTimeout(done, 0));
  expect(socket.sent.some(event => event.type === "session.commentary.append")).toBe(false);
  expect(live.liveVoiceState().pending).toBeNull();
});

